//! Dunnett means comparisons and cross tabulation against numbers from scipy 1.18.1. (Holm is not here: main
//! checks it against Origin, see `origin_stats4_tests.rs`.)
//!
//! These are scipy's numbers, NOT Origin's: how Origin presents these tools has not been measured (see
//! `docs/spec/statistics.md`, section 15). The reference script is `tools/scipy_stats_compare.py`, which wrote
//! `fixtures/scipy_stats_compare.rs`. All inputs were generated by us.
//!
//! Tolerances:
//! - Cross tabulation (chi-square, G, Yates, Fisher, expected counts): 1e-9 (relative, with 1e-12 absolute
//!   for tiny p-values).
//! - Dunnett statistics: 1e-9. Dunnett p-values and critical values against the script's own fine
//!   evaluation of the same integral: 1e-9 absolute (our Gauss-Legendre panels reach about 1e-12).
//! - Dunnett p-values against scipy.stats.dunnett itself: 5e-4 absolute. scipy integrates the multivariate
//!   t by quasi Monte Carlo (Genz and Bretz) and its own error is about 1e-4, so no tighter bound is honest;
//!   its confidence limits inherit that (compared to 0.02 absolute for these data).

#[path = "fixtures/scipy_stats_compare.rs"]
mod fixtures;

use fixtures::*;
use sheaf_calc::*;

fn near(name: &str, what: &str, got: f64, want: f64, rel: f64) {
    if want.is_nan() {
        assert!(got.is_nan(), "{name}: {what}: got {got:?}, want NaN");
        return;
    }
    if want.is_infinite() {
        assert_eq!(got, want, "{name}: {what}");
        return;
    }
    assert!((got - want).abs() <= rel * want.abs() + 1e-12, "{name}: {what}: got {got:?}, scipy gave {want:?}");
}

#[test]
fn dunnett_matches_scipy() {
    assert!(DUNNETT.len() >= 6);
    for c in DUNNETT {
        let all: Vec<&[f64]> = std::iter::once(c.control).chain(c.groups.iter().copied()).collect();
        let a = anova_one_way(&all).unwrap();
        let r = a.compare(MeansComparison::Dunnett, 0.05);
        assert_eq!(r.len(), c.groups.len(), "{}", c.name);
        let loadings = dunnett_loadings(&c.groups.iter().map(|g| g.len()).collect::<Vec<_>>(), c.control.len());
        let crit = dunnett_critical(0.05, &loadings, a.error.df);
        near(c.name, "critical value", crit, c.critical_ref, 1e-9);
        for (k, cmp) in r.iter().enumerate() {
            assert_eq!((cmp.i, cmp.j), (0, k + 1), "{}", c.name);
            near(c.name, "statistic", cmp.stat, c.statistic[k].abs(), 1e-9);
            assert!((cmp.p - c.p_ref[k]).abs() < 1e-9, "{}: p {k}: got {}, reference {}", c.name, cmp.p, c.p_ref[k]);
            assert!((cmp.p - c.p_scipy[k]).abs() < 5e-4, "{}: p {k}: got {}, scipy {}", c.name, cmp.p, c.p_scipy[k]);
            // Limits: the same critical value for every comparison.
            near(c.name, "lcl", cmp.lcl, cmp.diff - c.critical_ref * cmp.se, 1e-9);
            assert!(
                (cmp.lcl - c.ci_low_scipy[k]).abs() < 0.02,
                "{}: lcl {k}: {} vs {}",
                c.name,
                cmp.lcl,
                c.ci_low_scipy[k]
            );
            assert!(
                (cmp.ucl - c.ci_high_scipy[k]).abs() < 0.02,
                "{}: ucl {k}: {} vs {}",
                c.name,
                cmp.ucl,
                c.ci_high_scipy[k]
            );
            assert_eq!(cmp.significant, cmp.p < 0.05);
        }
    }
}

#[test]
fn dunnett_with_another_control_group() {
    let c = &DUNNETT[1];
    // Put the control last: the comparisons are the same, only the group numbers change.
    let mut all: Vec<&[f64]> = c.groups.to_vec();
    all.push(c.control);
    let a = anova_one_way(&all).unwrap();
    let r = a.compare_with_control(MeansComparison::Dunnett, all.len() - 1, 0.05);
    assert_eq!(r.len(), c.groups.len());
    for (k, cmp) in r.iter().enumerate() {
        assert_eq!((cmp.i, cmp.j), (all.len() - 1, k));
        assert!((cmp.p - c.p_ref[k]).abs() < 1e-9);
    }
}

#[test]
fn dunnett_with_one_treatment_is_the_two_sided_t_test() {
    let c = &DUNNETT[2];
    let all: Vec<&[f64]> = vec![c.control, c.groups[0]];
    let a = anova_one_way(&all).unwrap();
    let r = a.compare(MeansComparison::Dunnett, 0.05);
    let t = ttest_two(c.groups[0], c.control, 0.0, Tail::Two, 0.05, true).unwrap();
    assert!((r[0].p - t.p).abs() < 1e-9, "{} {}", r[0].p, t.p);
    assert!((r[0].p - c.p_ref[0]).abs() < 1e-9);
}

#[test]
fn crosstab_matches_scipy() {
    assert!(CROSSTAB.len() >= 9);
    for c in CROSSTAB {
        let t = Crosstab::new(c.counts.iter().map(|r| r.to_vec()).collect()).unwrap();
        for (erow, wrow) in t.expected.iter().zip(c.expected) {
            for (e, w) in erow.iter().zip(*wrow) {
                near(c.name, "expected", *e, *w, 1e-12);
            }
        }
        let p = t.pearson();
        near(c.name, "Pearson chi-square", p.statistic, c.pearson.0, 1e-9);
        near(c.name, "Pearson df", p.df, c.pearson.1, 0.0);
        near(c.name, "Pearson p", p.p, c.pearson.2, 1e-9);
        let g = t.likelihood_ratio();
        near(c.name, "G", g.statistic, c.likelihood_ratio.0, 1e-9);
        near(c.name, "G p", g.p, c.likelihood_ratio.2, 1e-9);
        match (t.yates(), c.yates) {
            (Some(y), Some((stat, p))) => {
                near(c.name, "Yates", y.statistic, stat, 1e-9);
                near(c.name, "Yates p", y.p, p, 1e-9);
            }
            (None, None) => {}
            _ => panic!("{}: Yates for 2 x 2 only", c.name),
        }
        match (t.fisher(), c.fisher) {
            (Some(f), Some((odds, two, less, greater))) => {
                near(c.name, "odds ratio", f.odds_ratio, odds, 1e-9);
                near(c.name, "Fisher two-sided", f.p_two_sided, two, 1e-9);
                near(c.name, "Fisher less", f.p_less, less, 1e-9);
                near(c.name, "Fisher greater", f.p_greater, greater, 1e-9);
            }
            (None, None) => {}
            _ => panic!("{}: Fisher for 2 x 2 only", c.name),
        }
    }
}
